"""Genuine Parquet fixtures generated by an independent upstream writer.

pyarrow is a host test dependency ONLY; the mobile reader is always exercised.
"""
from pathlib import Path
import gc
import tracemalloc
import pytest
pa = pytest.importorskip('pyarrow')
import pyarrow.parquet as pq
from ember._parquet import ParquetFile
from ember.ingest import ImportManager
from ember.corpus import Corpus


def write(path, rows, **kwargs):
    pq.write_table(pa.Table.from_pylist(rows), path, **kwargs)
    return path


@pytest.mark.parametrize('version', ['1.0', '2.0'])
@pytest.mark.parametrize('codec', ['NONE', 'snappy', 'gzip', 'zstd'])
@pytest.mark.parametrize('dictionary', [False, True])
def test_pages_unicode_null_provenance(tmp_path, version, codec, dictionary):
    rows=[{'text': f'Document {i} café 世界\nSecond paragraph.', 'url': f'https://example.org/{i}',
           'id':str(i), 'language':'en', 'dump':'CC-MAIN-2025-05'} for i in range(250)]
    rows[6]['text']=None
    path=write(tmp_path/'shard.parquet', rows, row_group_size=85, data_page_size=1024,
               data_page_version=version, compression=codec, use_dictionary=dictionary, write_batch_size=10)
    with ParquetFile(path) as reader:
        assert reader.num_rows == 250
        assert list(reader.rows()) == rows
        assert reader.row_groups_processed == 3
    corpus=Corpus(tmp_path/'corpus')
    manager=ImportManager(corpus)
    preview=manager.stage_path('one',path)
    assert preview['format']=='parquet' and preview['records']==250
    progress=[]
    result=manager.commit('one',on_progress=progress.append)
    assert result['outcome']=='completed'
    assert result['records']==250 and result['rejected']==1 and result['accepted']==249
    assert corpus.count()==249
    assert progress[-1]['rowGroupsProcessed']==3 and progress[-1]['percent']==100
    doc=corpus.get_document(next(corpus.iter_documents()).id)
    assert doc['meta']['language']=='en' and doc['meta']['sourceFile']=='shard.parquet'


def test_no_legacy_container_or_read_bytes_and_long_text(tmp_path, monkeypatch):
    import ember.ingest as ingest
    text='A long document with no lost ending. '*6000
    path=write(tmp_path/'large.parquet',[{'text':text,'id':'long'}])
    monkeypatch.setattr(ingest,'MAX_DECOMPRESSED_BYTES',1)
    monkeypatch.setattr(Path,'read_bytes',lambda *a:pytest.fail('whole-file read'))
    monkeypatch.setattr(ingest,'_iter_container_entries',lambda *a:pytest.fail('legacy container'))
    c=Corpus(tmp_path/'corpus');m=ImportManager(c)
    m.stage_path('one',path);m.commit('one')
    assert next(c.iter_documents()).text==text.strip()


def test_resume_cancel_rehydrate_and_shards(tmp_path):
    rows=[{'text':f'Unique row {i} with enough readable content.'} for i in range(350)]
    p=write(tmp_path/'one.parquet',rows,row_group_size=110)
    c=Corpus(tmp_path/'corpus');m=ImportManager(c);m.stage_path('one',p)
    def pause(event):
        if event['records']>=100:m.pause('one')
    partial=m.commit('one',on_progress=pause)
    assert partial['outcome']=='paused' and partial['records']<350
    m=ImportManager(c)
    assert m.commit('one')['outcome']=='completed'
    assert c.count()==350
    second=write(tmp_path/'two.parquet',rows+[{'text':'Another shard with unique additional content.'}])
    m.stage_path('two',second)
    out=m.commit('two')
    assert out['merged']+out['skipped']==350 and out['accepted']==1
    m.stage_path('cancel',p)
    def cancel(event):m.cancel('cancel')
    assert m.commit('cancel',on_progress=cancel)['outcome']=='cancelled'


def test_schema_empty_corrupt_changed_and_storage_failure(tmp_path, monkeypatch):
    c=Corpus(tmp_path/'corpus');m=ImportManager(c)
    missing=write(tmp_path/'missing.parquet',[{'url':'https://example.org'}])
    with pytest.raises(ValueError,match='text column'):m.stage_path('bad',missing)
    empty=tmp_path/'empty.parquet'
    pq.write_table(pa.table({'text':pa.array([],type=pa.string())}),empty)
    m.stage_path('empty',empty)
    assert m.commit('empty')['records']==0
    p=write(tmp_path/'ok.parquet',[{'text':f'Document {i}.'} for i in range(250)])
    m.stage_path('one',p)
    original=c.add_many
    calls=0
    def disk_full(batch):
        nonlocal calls
        calls+=1
        if calls==2:raise OSError('database or disk is full')
        return original(batch)
    monkeypatch.setattr(c,'add_many',disk_full)
    with pytest.raises(OSError,match='disk is full'):m.commit('one')
    assert c.count()==100 and m._jobs['one'].records==100 and m._jobs['one'].status=='failed'
    monkeypatch.setattr(c,'add_many',original)
    assert ImportManager(c).resume('one')['records']==250
    m.stage_path('changed',p)
    with p.open('ab') as f:f.write(b'changed')
    with pytest.raises(ValueError,match='changed'):m.commit('changed')
    with pytest.raises(ValueError,match='Parquet'):m.stage_path('truncated',p)
    nested=write(tmp_path/'nested.parquet',[{'text':['one','two']}])
    with pytest.raises(ValueError,match='nested'):m.stage_path('nested',nested)


def test_page_bounded_not_row_group_bounded(tmp_path):
    p=tmp_path/'large-group.parquet'
    # Single row group much larger than an individual page; no full group lists.
    values=[f'{i:06d} '+('abcdefghij '*200) for i in range(12000)]
    pq.write_table(pa.table({'text':values}),p,row_group_size=12000,
                   data_page_size=32768,write_batch_size=16,use_dictionary=False,compression='NONE')
    del values
    gc.collect();tracemalloc.start()
    with ParquetFile(p) as reader:
        assert sum(1 for _ in reader.rows())==12000
    _,peak=tracemalloc.get_traced_memory();tracemalloc.stop()
    assert peak<4*1024*1024,peak


def test_running_manifest_is_durable_before_first_batch(tmp_path, monkeypatch):
    p=write(tmp_path/'interrupt.parquet',[{'text':'An uncommitted first document.'}])
    c=Corpus(tmp_path/'corpus');m=ImportManager(c);m.stage_path('one',p)
    def killed_before_processing(*args):
        # Simulate process death before the normal import try/finally can run.
        raise KeyboardInterrupt()
    monkeypatch.setattr(m,'_commit_parquet',killed_before_processing)
    with pytest.raises(KeyboardInterrupt):m.commit('one')
    recovered=ImportManager(c)
    assert recovered._jobs['one'].status=='paused'
    assert recovered._jobs['one'].records==0
    assert recovered.resume('one')['accepted']==1
